        eventNarrative: `في مساء الخميس الموافق ١٣ أغسطس ٢٠٢٦، أقام المجني عليه كمال الدين منصور حفل عشاء خاصاً في قصره بمناسبة عيد ميلاده الثامن والستين، بحضور عدد محدود من أفراد عائلته وعدد من المقربين.

بدأ الحفل في الساعة الثامنة مساءً وانتهى العشاء الرسمي حوالي العاشرة والنصف، فتفرق الضيوف بين حديقة القصر وصالة الاستقبال. وفي حوالي الساعة الحادية عشرة مساءً، اعتذر المجني عليه لضيوفه وصعد إلى جناحه الخاص في الطابق الثاني.

في تمام الساعة الثانية عشرة والنصف صباحاً، أفاق الطاهي الخاص رامي شوقي نتيجة سماعه صوت سقوط من الطابق العلوي. صعد للتحقق فوجد باب الجناح مفتوحاً ووجد المجني عليه ملقىً على الأرض بجانب مكتبه.

تبيّن أن وقت الوفاة كان بين الساعة الحادية عشرة مساءً والثانية عشرة والربع صباحاً.

⚠ التشخيص الأولي أشار إلى احتمال أزمة قلبية — غير أن نتائج الطب الشرعي أثبتت خلاف ذلك تماماً.`,

        crimeScene: `وصل فريق المعاينة في الساعة الثالثة والنصف فجراً. الجناح الخاص في الطرف الجنوبي من الطابق الثاني.

المشروب: كوب ويسكي على المكتب — به بقايا سائل. أُرسل للتحليل الفوري.
الدواء: علبة حبوب ضغط الدم — فارغة تماماً رغم أنها كانت تحتوي على ٧ حبات في الصباح وفقاً للممرضة الخاصة.
الهاتف: موجود على المكتب — آخر مكالمة الساعة ١٠:٥٧ مساءً — آخر نشاط: تطبيق الملاحظات ١١:٠٧ مساءً.
نافذة الجناح: مغلقة من الداخل.
الباب الرئيسي: لا أثر اقتحام.
⚠ الباب الجانبي للجناح: يُطل على الشرفة الشمالية — لم يُفحص أولاً.`,

        forensicSummary: `أفاد د. نادر عوض:
— سبب الوفاة: تسمم حاد بجرعة مضاعفة من دواء الأملوديبين — ثلاثة أضعاف الجرعة المميتة.
— الدواء وُجد مُذاباً في كوب الويسكي.
— التسمم بطيء التأثير — لا يُسبب ألماً حاداً — المجني عليه أُسقط في غيبوبة تدريجية.
— لا آثار لعنف جسدي. لا أثر لاقتحام من النافذة.
— وقت الوفاة: بين ١١:١٠ مساءً و ١٢:١٥ صباحاً.
⚠ مَن نفّذ الجريمة كان يعلم بالدقيق الجرعة اللازمة للقتل وتأثير التفاعل مع الكحول.`,

