      title: "رابعاً: التقرير الفني والتحليل الجنائي المعمّق",
      sections: [
        {
          subtitle: "أ — تحليل رسالة الانتحار",
          content: `الرسالة:
— مطبوعة على الطابعة — بخط Times New Roman — حجم ١٢.
— توقيع يدوي في الأسفل — يتطابق مع توقيع سامر.

⚠ مشكلة الطباعة:
سامر كاتب يحمل قلماً دائماً — كل مسوداته بخط يده — حتى قوائم التسوق.
في كل رسائله الشخصية الموثقة: لا توجد رسالة مطبوعة واحدة.
في روايته "الأسرار": وصف مشهد انتحار شخصية — الشخصية كتبت رسالتها بخط يدها.

⚠ مشكلة الأسلوب:
مقارنة نصية بين الرسالة وكتابات سامر:
— سامر يستخدم جملاً طويلة معقدة — الرسالة: جمل قصيرة مباشرة.
— سامر لا يستخدم أبداً عبارة "أتمنى لكم السلام" — الرسالة تنتهي بها.
— سامر يُوقّع اسمه الثلاثي دائماً: "سامر فريد حلمي" — التوقيع على الرسالة: "سامر فريد" فقط.

⚠ التوقيع ناقص — هل نسي؟ أم نُسخ التوقيع من ورقة أخرى؟`,
        },
        {
          subtitle: "ب — تحليل اليد والمسدس",
          content: `سامر أعسر — موثق في:
— رخصة قيادته (خانة اليد المفضلة).
— شهادات ٧ أشخاص من محيطه.
— صوره الشخصية على مدى ٣٠ سنة.

في إطلاق نار انتحاري من أعسر:
— المسدس في اليد اليسرى.
— الرصاصة تدخل من الصدغ الأيسر أو من الفم.
— البارود: على راحة اليد اليسرى وبطانة الأصابع.

ما وُجد فعلاً:
— المسدس في اليد اليمنى.
— الرصاصة دخلت من الصدغ الأيمن.
— البارود: على ظاهر اليد اليمنى فقط.

⚠ تفسير واحد منطقي: وُضع المسدس في اليد اليمنى بعد الإطلاق — البارود انتقل من ظاهر المسدس لظاهر اليد وليس العكس.`,
        },
        {
          subtitle: "ج — تحليل اللابتوب والملفات",
          content: `لابتوب سامر — الحالة عند الاكتشاف:
— مفتوح — الشاشة تُظهر سطح المكتب.
— ملف الرواية "الأسرار" محذوف.
— سجل الحذف: الملف حُذف الساعة ١١:١٢ مساءً.

⚠ وقت الوفاة المقدَّر: بين ١١:٠٠ و١:٠٠ صباحاً.
⚠ إذا مات سامر حوالي ١١:٠٠ — فمن حذف الملف الساعة ١١:١٢؟
⚠ إذا مات بعد ١١:١٢ — فلماذا حذف روايته قبل أن يُطلق النار؟

سجل الطابعة:
— رسالة الانتحار طُبعت الساعة ١٠:٤٧ مساءً.
— قبل وقت الوفاة المقدَّر — هذا طبيعي لو كان انتحاراً.
— لكن: سجل اللابتوب يُثبت أن ملف الرسالة أُنشئ الساعة ١٠:٣٩ وعُدِّل ١٠:٤٥.
⚠ ٦ دقائق لكتابة رسالة انتحار — هذا ممكن. لكن:
⚠ آخر ملف فتحه سامر قبل الرسالة: فصل من الرواية — الساعة ١٠:٣٠. 
⚠ يعني: كان يعمل على روايته — ثم فجأة كتب رسالة انتحار — ثم أطلق النار؟`,
        },
        {
          subtitle: "د — أعقاب السجائر",
          content: `ثلاثة أعقاب سجائر في الطفاية على مكتب سامر.

سامر: لم يُدخن منذ أبريل ٢٠٢١ — موثق طبياً.

الماركة: نوفا سلاتس — علبة زرقاء.

من يدخن هذه الماركة من المشتبه بهم؟
— لميس طاهر: مدخنة — ماركتها نوفا سلاتس — موثق في صورها على السوشيال ميديا.
— باقي المشتبه بهم: لا توجد معلومات عن تدخينهم لهذه الماركة.

⚠ ثلاثة أعقاب تعني جلوساً طويلاً في المكتب — ليس زيارة عابرة.
⚠ لميس أقرب المشتبه بهم لهذا الدليل — ولديها مفتاح الشقة.`,
        },
        {
          subtitle: "هـ — المزلاج والدخول المستحيل",
          content: `باب الشقة وُجد مقفلاً من الداخل بـ:
١- قفل الباب الرئيسي (يُغلق بالمفتاح من الداخل والخارج).
٢- المزلاج الداخلي (يُغلق يدوياً من الداخل فقط — ظاهرياً).

⚠ لكن: نوع المزلاج المُركَّب في الشقة: Secura-Slide 3B.
⚠ Secura-Slide 3B: يمكن إغلاقه من الخارج بأداة رفيعة (سلك أو مسطرة رفيعة) إذا بقيت الفجوة بين الباب والإطار أقل من ٣ مم.
⚠ الفجوة في باب هذه الشقة: ٢.٧ مم — كافية.
⚠ هذه الحيلة تستلزم معرفة مسبقة بنوع المزلاج — أو تجربة مسبقة على الباب.
⚠ لميس دخلت الشقة مرات عديدة بمفتاحها — تعرف الباب جيداً.`,
        },
      ],
