          content: `ملف الشرطة القديم — رقم ١٨٨٤ / ٢٠٠٦:
الوثائق المتوفرة:
— بلاغ الاختفاء: مُقدَّم من وائل رضا — ٢٩ أكتوبر ٢٠٠٦.
— إفادة هناء: قدّمتها ٣١ أكتوبر — تقول إنه كان "متوتراً قبل الاختفاء".
— إفادة رامي الأولى: رآه الساعة ٨ مساءً يوم ٢٧ أكتوبر.
— إفادة رامي الثانية (بعد أسبوع): رآه الساعة ٦ مساءً.
— إفادة رامي الثالثة (بعد شهر): لم يره ذلك اليوم أصلاً.

الوثيقة المفقودة:
— رسالة خالد لوائل: مُسجَّلة كمُستلَمة في الملف — لكنها غير موجودة في المحتوى.
— توقيع الاستلام: المحقق الأصلي / مُلازم أول رمزي طاهر.
⚠ رمزي طاهر: أُحيل للتقاعد المبكر ٢٠٠٧ — يعيش الآن في الإسكندرية.
⚠ هل المحقق القديم جزء من المنظومة؟`
