    page4: {
      title: "رابعاً: التقرير الهندسي والجنائي — آلية الجريمة",
      sections: [
        {
          subtitle: "أ — آلية نظام القتل",
          content: `تقرير م. سلمى الرشيد — خبيرة البنية التحتية:

الغرفة ٣١٧ — النظام المُكتشَف:

١- أنبوب التهوية الرئيسي:
يصل من الخارج → يمر بممر الصيانة → يدخل الغرفة.
في الممر: صمام يدوي مُثبَّت على الأنبوب — غير مُدرَج في أي مخطط رسمي.

٢- الموقع الحرج:
الأنبوب يمر بجانب حجرة المراجل مباشرة.
في الحجرة: ٣ مراجل غاز طبيعي لتدفئة الفندق.
المراجل في الحالة العادية: تُنتج كميات صغيرة من CO تُخرجها التهوية.

٣- آلية التسمم:
الصمام يُغلق → هواء الغرفة يُعاد تدويره → CO من المراجل ينزّ عبر الأنابيب ويتراكم.
في ٢-٣ ساعات مع شخص نائم: التركيز يصل للجرعة المميتة.
الضحية تنام → لا تشعر بشيء → لا تستيقظ.

٤- الذكاء في التصميم:
لا بصمات في الغرفة.
لا أدوية أو مواد غريبة.
الجثة لا تحمل أي دليل على عنف.
أعراض التسمم بـCO تشبه تماماً القصور القلبي المفاجئ.
الفحص الروتيني لا يشمل CO إلا إذا طُلب تحديداً.

⚠ هذا النظام لو لم تكتشفه سلمى — ظل مخفياً للأبد.`
        },
        {
          subtitle: "ب — إعادة فحص الوفيتين السابقتين",
          content: `إعادة التقييم الطبي الجنائي:

إدريس نبيل — ٢٠١٤:
— التقرير الأصلي: قصور قلبي.
— لم يُحفَظ دم لعينات لاحقة — إجراء غير مُلزِم وقتها.
— سامية (زوجته): أفاقت بصداع شديد وغثيان — لم تُبلَّغ عنها كأعراض.
— الآن: المحقق يستدعي وثائق الفحص القديمة — وُجد في التقرير الطبي ملاحظة صغيرة أُهملت: "احمرار خفيف في الشفتين" — احمرار الشفتين: أحد علامات التسمم بـCO.

محسن طاهر — ٢٠١٩:
— التقرير الأصلي: Sleep Apnea حاد.
— عائلته تؤكد: حالته كانت خفيفة لا تُسبب الوفاة.
— الفندق غيّر مفروشات الغرفة فور الوفاة — إتلاف أدلة محتملة.
— لا عينات دم محفوظة.

⚠ الوفيتان بالأرجح نفس الآلية — لكن لا إثبات مادي بعد.
⚠ الدليل الوحيد: شهادة سامية عن أعراضها + ملاحظة احمرار الشفتين.`
        },
        {
          subtitle: "ج — من أغلق الصمام في كل وفاة؟",
          content: `التحليل الزمني:

الصمام يحتاج للإغلاق يدوياً في ممر الصيانة.
الممر يُفتح ببطاقة خاصة — سجل دخول إلكتروني.

سجل دخول ممر الصيانة:
— ليلة وفاة إدريس (سبتمبر ٢٠١٤): دخول الساعة ١١:٤٥ مساءً — ببطاقة مسجلة باسم "صيانة — مجهول" — لا اسم.
— ليلة وفاة محسن (مارس ٢٠١٩): دخول الساعة ١٢:٣٠ صباحاً — نفس البطاقة.
— ليلة حادثة لورا (يناير ٢٠٢٤): دخول الساعة ١٠:٥٠ مساءً — نفس البطاقة.

⚠ البطاقة "صيانة — مجهول": بطاقة ثالثة غير مُدرجة في النظام الرسمي.
⚠ وجود بطاقة مجهولة = زكريا أو من يعمل بأمره.
⚠ في كل ليلة: البطاقة دخلت ودخلت مرة ثانية بعد الوفاة بساعتين — للإعادة والفتح.`
        },
        {
          subtitle: "د — اكتشاف المفاجأة: الغرفة ٣١٧ كانت مُصمَّمة من البداية",
          content: `فحص مخططات البناء الأصلية — ٢٠١٢:

في المخططات الرسمية المقدمة لرخصة البناء: الغرفة ٣١٧ تهويتها عادية.
في المخططات التفصيلية الداخلية (غير المقدمة رسمياً): الصمام موجود وتصميمه مختلف.

⚠ مخططان مختلفان: للرسمية — وللتنفيذ.
⚠ هذا يعني أن الغرفة صُمِّمت لتكون أداة قتل قبل افتتاح الفندق.
⚠ التصميم المدروس يستلزم معرفة مسبقة بالضحية المستهدفة — إدريس نبيل.
⚠ زكريا بنى الفندق بهدف محدد: قتل شريكه التجاري الذي يرفض الاستسلام في النزاع.
⚠ الضحيتان اللاحقتان: حجزتا الغرفة بالصدفة — لم يكونا مستهدفَين شخصياً.`
        }
      ]
    },

