                content: `من: bakr@kalima-press.eg\nإلى: evidence@niyaba-cairo.gov.eg\nالتاريخ: ١٩/٠٦/٢٠٢٦ — ٠١:٠٠ صباحاً\nالموضوع: أدلة — قضية محتملة\n─────────────────────────\n"إلى النيابة —\n\nإذا وصل هذا البريد وأنا غير موجود:\nالكتاب 'أربعون عاماً خلف الكواليس' يحتوي رسالة مشفرة.\nالمفتاح: الحرف الأول من كل جملة في كل فصل زوجي.\nالنتيجة: اسم مسؤول خان وطنه عام ١٩٩٩.\nالدليل الصوتي: مع السفير منصور البنا — في الإسكندرية.\n\nالشخص الذي سيأتي الساعة الواحدة يدّعي أنه يريد 'النقاش'.\nأعرف ما يريده فعلاً.\nلكن لن أسلم. الحقيقة لا تُسلَّم.\n\n— بكر سعيد عثمان"\n─────────────────────────\n⚠ بكر أرسل البريد قبل وصول ثابت بدقيقتين.\n⚠ كان يعلم أنه في خطر — ووثّق كل شيء.`
